actions.content:
"""Contratos seguros para el Asistente IA contextual.

Este modulo no ejecuta SQL, no resuelve permisos y no acepta URLs/rutas.
Solo normaliza metadata de vista y valida acciones UI contra whitelists.
"""

from __future__ import annotations

import json
import re
from typing import Any, Dict, List, Mapping

MAX_CONTEXT_STRING = 500
MAX_CONTEXT_LIST = 50
MAX_ACTIONS = 3

VIEW_KEYS = {
    "modulo",
    "view_id",
    "titulo",
    "scope",
    "filtros",
    "periodo",
    "unidad_negocio",
    "seleccion",
    "columnas_visibles",
    "estado_vista",
}

ACTION_TYPES = {"APPLY_FILTERS", "CLEAR_FILTERS", "OPEN_VIEW"}
FILTER_KEYS = {
    "ventas_min",
    "ventas_max",
    "pax_min",
    "pax_max",
    "ticket_contiene",
}
VIEW_TYPES = {"table", "bar_chart", "line_chart", "kpi_cards"}
VIEW_DATASETS = {"tickets", "lines"}

_SENSITIVE_MARKERS = (
    "password",
    "passwd",
    "token",
    "api_key",
    "apikey",
    "secret",
    "credential",
    "authorization",
    "cookie",
    "connection",
)


def _safe_key(value: Any) -> str:
    return re.sub(r"[^a-z0-9_]+", "_", str(value or "").strip().lower())


def _safe_value(value: Any, depth: int = 0) -> Any:
    if depth > 4:
        return None
    if value is None or isinstance(value, (bool, int, float)):
        return value
    if isinstance(value, str):
        return value[:MAX_CONTEXT_STRING]
    if isinstance(value, Mapping):
        result: Dict[str, Any] = {}
        for index, (key, item) in enumerate(value.items()):
            if index >= MAX_CONTEXT_LIST:
                break
            normalized = _safe_key(key)
            if any(marker in normalized for marker in _SENSITIVE_MARKERS):
                continue
            result[str(key)[:80]] = _safe_value(item, depth + 1)
        return result
    if isinstance(value, (list, tuple)):
        return [_safe_value(item, depth + 1) for item in list(value)[:MAX_CONTEXT_LIST]]
    return str(value)[:MAX_CONTEXT_STRING]


def normalize_view_context(raw: Any) -> Dict[str, Any]:
    if not isinstance(raw, Mapping):
        return {}

    result: Dict[str, Any] = {}
    for key in VIEW_KEYS:
        if key in raw:
            result[key] = _safe_value(raw.get(key))

    return result


def action_prompt(
    user_text: str,
    assistant_text: str,
    view_context: Mapping[str, Any],
) -> str:
    visible = view_context.get("columnas_visibles") or []
    return (
        "SOLICITUD DEL USUARIO:\n"
        + str(user_text or "")[:4000]
        + "\n\nRESPUESTA DEL ASISTENTE:\n"
        + str(assistant_text or "")[:6000]
        + "\n\nCONTEXTO DE VISTA NO AUTORITATIVO:\n"
        + json.dumps(dict(view_context), ensure_ascii=False, default=str)[:8000]
        + "\n\nCOLUMNAS VISIBLES DECLARADAS:\n"
        + json.dumps(visible, ensure_ascii=False, default=str)[:3000]
    )


def _column_keys(view_context: Mapping[str, Any]) -> set[str]:
    keys: set[str] = set()
    for row in view_context.get("columnas_visibles") or []:
        if isinstance(row, Mapping):
            value = str(row.get("key") or "").strip()
        else:
            value = str(row or "").strip()
        if value:
            keys.add(value)
    return keys


def validate_actions(payload: Any, view_context: Mapping[str, Any]) -> List[Dict[str, Any]]:
    if not isinstance(payload, Mapping):
        return []

    rows = payload.get("actions") or []
    if not isinstance(rows, list):
        return []

    allowed_columns = _column_keys(view_context)
    result: List[Dict[str, Any]] = []

    for raw in rows[:MAX_ACTIONS]:
        if not isinstance(raw, Mapping):
            continue

        action_type = str(raw.get("type") or "").strip().upper()
        if action_type not in ACTION_TYPES:
            continue

        label = str(raw.get("label") or "").strip()[:80]
        if not label:
            label = {
                "APPLY_FILTERS": "Aplicar filtro",
                "CLEAR_FILTERS": "Limpiar filtros",
                "OPEN_VIEW": "Abrir vista",
            }[action_type]

        if action_type == "CLEAR_FILTERS":
            result.append({"type": action_type, "label": label, "payload": {}})
            continue

        data = raw.get("payload") or {}
        if not isinstance(data, Mapping):
            continue

        if action_type == "APPLY_FILTERS":
            filters = data.get("filters") or {}
            if not isinstance(filters, Mapping):
                continue
            safe_filters: Dict[str, Any] = {}
            for key, value in filters.items():
                key = str(key)
                if key not in FILTER_KEYS:
                    continue
                if key == "ticket_contiene":
                    safe_filters[key] = str(value or "")[:64]
                else:
                    try:
                        safe_filters[key] = float(value)
                    except (TypeError, ValueError):
                        continue
            if safe_filters:
                result.append({
                    "type": action_type,
                    "label": label,
                    "payload": {"filters": safe_filters},
                })
            continue

        view_type = str(data.get("view_type") or "").strip().lower()
        dataset = str(data.get("dataset") or "").strip().lower()
        if view_type not in VIEW_TYPES or dataset not in VIEW_DATASETS:
            continue

        payload_out: Dict[str, Any] = {
            "view_type": view_type,
            "dataset": dataset,
            "title": str(data.get("title") or "Análisis IA")[:120],
        }

        for key in ("x_key", "y_key"):
            value = str(data.get(key) or "").strip()
            if value and value in allowed_columns:
                payload_out[key] = value

        result.append({
            "type": action_type,
            "label": label,
            "payload": payload_out,
        })

    return result


def parse_actions_response(raw: str, view_context: Mapping[str, Any]) -> List[Dict[str, Any]]:
    text = str(raw or "").strip()
    start = text.find("{")
    end = text.rfind("}")
    if start < 0 or end <= start:
        return []
    try:
        payload = json.loads(text[start:end + 1])
    except (TypeError, ValueError, json.JSONDecodeError):
        return []
    return validate_actions(payload, view_context)

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { BarChart3, Bot, Loader2, Send, Sparkles, X } from 'lucide-react';
import {
  crearSesion,
  enviarMensaje,
  iaHealth,
} from '../../services/iaAssistantApi';

const VIEW_TYPES = new Set(['table', 'bar_chart', 'line_chart', 'kpi_cards']);

const numberValue = (value) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
};

export function IAAnalysisModal({ config, rows, onClose }) {
  if (!config || !VIEW_TYPES.has(config.view_type)) return null;
  const safeRows = Array.isArray(rows) ? rows.slice(0, 100) : [];
  const keys = safeRows.length ? Object.keys(safeRows[0]).slice(0, 8) : [];
  const xKey = keys.includes(config.x_key) ? config.x_key : keys[0];
  const yKey = keys.includes(config.y_key) ? config.y_key : keys.find(
    (key) => safeRows.some((row) => Number.isFinite(Number(row?.[key])))
  );
  const maxValue = Math.max(1, ...safeRows.map((row) => numberValue(row?.[yKey])));

  return (
    <div className="fixed inset-0 z-[80] flex items-center justify-center bg-black/70 p-6">
      <div className="max-h-[82vh] w-full max-w-4xl overflow-hidden rounded-2xl border border-slate-600 bg-slate-900 shadow-2xl">
        <header className="flex items-center justify-between border-b border-slate-700 px-5 py-3">
          <div>
            <h3 className="font-semibold text-white">{config.title || 'Análisis IA'}</h3>
            <p className="text-xs text-slate-400">Vista temporal · no modifica datos</p>
          </div>
          <button type="button" onClick={onClose} className="rounded-lg p-2 text-slate-300 hover:bg-slate-800">
            <X className="h-4 w-4" />
          </button>
        </header>

        <div className="max-h-[70vh] overflow-auto p-5">
          {config.view_type === 'table' && (
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left text-xs text-slate-400">
                  {keys.map((key) => <th key={key} className="px-3 py-2">{key}</th>)}
                </tr>
              </thead>
              <tbody>
                {safeRows.map((row, index) => (
                  <tr key={index} className="border-t border-slate-800 text-slate-200">
                    {keys.map((key) => <td key={key} className="px-3 py-2">{String(row?.[key] ?? '—')}</td>)}
                  </tr>
                ))}
              </tbody>
            </table>
          )}

          {config.view_type === 'kpi_cards' && (
            <div className="grid gap-3 md:grid-cols-3">
              <div className="rounded-xl border border-slate-700 p-4">
                <p className="text-xs text-slate-400">Registros visibles</p>
                <p className="mt-1 text-2xl font-bold text-white">{safeRows.length}</p>
              </div>
              {yKey && (
                <>
                  <div className="rounded-xl border border-slate-700 p-4">
                    <p className="text-xs text-slate-400">Suma {yKey}</p>
                    <p className="mt-1 text-2xl font-bold text-white">
                      {safeRows.reduce((sum, row) => sum + numberValue(row?.[yKey]), 0).toLocaleString('es-MX')}
                    </p>
                  </div>
                  <div className="rounded-xl border border-slate-700 p-4">
                    <p className="text-xs text-slate-400">Promedio {yKey}</p>
                    <p className="mt-1 text-2xl font-bold text-white">
                      {(safeRows.length
                        ? safeRows.reduce((sum, row) => sum + numberValue(row?.[yKey]), 0) / safeRows.length
                        : 0).toLocaleString('es-MX', { maximumFractionDigits: 2 })}
                    </p>
                  </div>
                </>
              )}
            </div>
          )}

          {config.view_type === 'bar_chart' && (
            <div className="space-y-2">
              {safeRows.slice(0, 25).map((row, index) => {
                const value = numberValue(row?.[yKey]);
                return (
                  <div key={index} className="grid grid-cols-[180px_1fr_100px] items-center gap-3 text-sm">
                    <span className="truncate text-slate-300">{String(row?.[xKey] ?? index + 1)}</span>
                    <div className="h-3 rounded-full bg-slate-800">
                      <div className="h-3 rounded-full bg-indigo-500" style={{ width: `${Math.max(1, (value / maxValue) * 100)}%` }} />
                    </div>
                    <span className="text-right text-slate-300">{value.toLocaleString('es-MX')}</span>
                  </div>
                );
              })}
            </div>
          )}

          {config.view_type === 'line_chart' && (
            <div>
              <svg viewBox="0 0 800 260" className="h-72 w-full rounded-xl bg-slate-950/40 p-4">
                <polyline
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="3"
                  className="text-indigo-400"
                  points={safeRows.slice(0, 40).map((row, index, arr) => {
                    const x = arr.length <= 1 ? 20 : 20 + (760 * index / (arr.length - 1));
                    const y = 235 - (210 * numberValue(row?.[yKey]) / maxValue);
                    return `${x},${y}`;
                  }).join(' ')}
                />
              </svg>
              <p className="mt-2 text-xs text-slate-500">
                {xKey || 'índice'} · {yKey || 'valor'}
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export function IAContextualPanel({
  open,
  onClose,
  contextoVista,
  viewData,
  onApplyFilters,
  onClearFilters,
}) {
  const [sessionId, setSessionId] = useState(null);
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [sending, setSending] = useState(false);
  const [analysis, setAnalysis] = useState(null);
  const scrollRef = useRef(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, sending]);

  if (!open) return null;

  const executeAction = (action) => {
    if (action?.type === 'APPLY_FILTERS') {
      onApplyFilters?.(action.payload?.filters || {});
      return;
    }
    if (action?.type === 'CLEAR_FILTERS') {
      onClearFilters?.();
      return;
    }
    if (action?.type === 'OPEN_VIEW' && VIEW_TYPES.has(action.payload?.view_type)) {
      const dataset = action.payload?.dataset === 'lines' ? 'lines' : 'tickets';
      setAnalysis({ ...action.payload, dataset });
    }
  };

  const send = async () => {
    const text = input.trim();
    if (!text || sending) return;
    setInput('');
    setMessages((prev) => [...prev, { role: 'user', text }]);
    setSending(true);
    try {
      let sid = sessionId;
      if (!sid) {
        const created = await crearSesion('Comercial · Drilldown contextual');
        sid = created?.sesion?.sesion_id;
        setSessionId(sid);
      }
      const response = await enviarMensaje(sid, text, contextoVista);
      setMessages((prev) => [
        ...prev,
        {
          role: 'assistant',
          text: response?.respuesta || '',
          actions: Array.isArray(response?.acciones_ui) ? response.acciones_ui : [],
        },
      ]);
    } catch (error) {
      setMessages((prev) => [
        ...prev,
        { role: 'assistant', text: 'No fue posible obtener una respuesta del Asistente IA.' },
      ]);
    } finally {
      setSending(false);
    }
  };

  return (
    <>
      <div className="absolute inset-y-0 right-0 z-[70] flex w-full max-w-md flex-col border-l border-slate-700 bg-slate-950 shadow-2xl">
        <header className="flex items-center justify-between border-b border-slate-800 px-4 py-3">
          <div className="flex items-center gap-2">
            <Sparkles className="h-4 w-4 text-indigo-400" />
            <div>
              <p className="text-sm font-semibold text-white">Asistente IA</p>
              <p className="text-[11px] text-slate-500">Contexto: Comercial / Drilldown</p>
            </div>
          </div>
          <button type="button" onClick={onClose} className="rounded-lg p-2 text-slate-400 hover:bg-slate-800">
            <X className="h-4 w-4" />
          </button>
        </header>

        <div ref={scrollRef} className="flex-1 space-y-4 overflow-y-auto p-4">
          {messages.length === 0 && (
            <div className="rounded-xl border border-slate-800 bg-slate-900/60 p-4 text-sm text-slate-300">
              <Bot className="mb-2 h-5 w-5 text-indigo-400" />
              Pregunta sobre los tickets, filtros o la selección actual. El Asistente usa el mismo servicio IA de EDARSAHUB.
            </div>
          )}
          {messages.map((message, index) => (
            <div key={index} className={message.role === 'user' ? 'text-right' : 'text-left'}>
              <div className={`inline-block max-w-[90%] whitespace-pre-wrap rounded-2xl px-4 py-3 text-sm ${
                message.role === 'user'
                  ? 'bg-indigo-600 text-white'
                  : 'border border-slate-800 bg-slate-900 text-slate-200'
              }`}>
                {message.text}
              </div>
              {message.role === 'assistant' && (message.actions || []).length > 0 && (
                <div className="mt-2 flex flex-wrap gap-2">
                  {message.actions.map((action, actionIndex) => (
                    <button
                      key={`${action.type}:${actionIndex}`}
                      type="button"
                      onClick={() => executeAction(action)}
                      className="rounded-lg border border-indigo-500/50 bg-indigo-500/10 px-3 py-1.5 text-xs font-medium text-indigo-300 hover:bg-indigo-500/20"
                    >
                      {action.label}
                    </button>
                  ))}
                </div>
              )}
            </div>
          ))}
          {sending && (
            <div className="flex items-center gap-2 text-sm text-slate-400">
              <Loader2 className="h-4 w-4 animate-spin" /> Analizando…
            </div>
          )}
        </div>

        <div className="border-t border-slate-800 p-4">
          <div className="flex items-end gap-2 rounded-xl border border-slate-700 bg-slate-900 p-2">
            <textarea
              rows={2}
              value={input}
              onChange={(event) => setInput(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' && !event.shiftKey) {
                  event.preventDefault();
                  send();
                }
              }}
              placeholder="Pregunta sobre esta vista…"
              className="flex-1 resize-none bg-transparent px-2 py-1 text-sm text-white outline-none placeholder:text-slate-500"
            />
            <button
              type="button"
              disabled={!input.trim() || sending}
              onClick={send}
              className="rounded-lg bg-indigo-600 p-2 text-white disabled:opacity-40"
            >
              <Send className="h-4 w-4" />
            </button>
          </div>
        </div>
      </div>

      <IAAnalysisModal
        config={analysis}
        rows={analysis ? (viewData?.[analysis.dataset] || []) : []}
        onClose={() => setAnalysis(null)}
      />
    </>
  );
}

export function IAContextualLauncher(props) {
  const [allowed, setAllowed] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    let active = true;
    iaHealth()
      .then(() => {
        if (active) setAllowed(true);
      })
      .catch(() => {
        if (active) setAllowed(false);
      });
    return () => {
      active = false;
    };
  }, []);

  if (!allowed) return null;

  return (
    <>
      <button
        type="button"
        data-testid="ia-contextual-launcher"
        onClick={() => setOpen(true)}
        className="flex items-center gap-1.5 rounded-lg border border-indigo-500/40 bg-indigo-500/10 px-3 py-1.5 text-sm font-medium text-indigo-300 hover:bg-indigo-500/20"
      >
        <Sparkles className="h-4 w-4" />
        Asistente IA
      </button>
      <IAContextualPanel {...props} open={open} onClose={() => setOpen(false)} />
    </>
  );
}

export default IAContextualLauncher;

actions.old:
"""Endpoints protegidos del Asistente IA."""

from __future__ import annotations

from typing import Optional
from uuid import UUID

from fastapi import (
    APIRouter,
    Depends,
    HTTPException,
    Request,
)
from pydantic import BaseModel, Field

from core.rbac.middleware import (
    require_explicit_permission,
)
from modules.ia_assistant import query_bridge
from modules.ia_assistant import repository
from modules.ia_assistant import service
from modules.ia_assistant.worker_routes import router as worker_router

IA_PERMISSION = "IA_ASSISTANT_VER"

router = APIRouter(
    prefix="/ia",
    tags=["Asistente IA"],
)
router.include_router(worker_router)


class CrearSesionRequest(BaseModel):
    titulo: Optional[str] = Field(
        default=None,
        max_length=300,
    )


class ChatRequest(BaseModel):
    sesion_id: UUID
    mensaje: str = Field(
        ...,
        min_length=1,
        max_length=8000,
    )


def _current_email(
    current_user: dict,
) -> str:
    email = str(
        current_user.get("email")
        or ""
    ).strip().lower()

    if not email:
        raise HTTPException(
            status_code=403,
            detail={
                "error": (
                    "IDENTIDAD_INCOMPLETA"
                ),
                "mensaje": (
                    "El usuario autenticado "
                    "no contiene una identidad "
                    "de email válida"
                ),
            },
        )

    return email


def _translate_error(
    exc: Exception,
) -> None:
    if isinstance(
        exc,
        service.SessionNotFoundError,
    ):
        raise HTTPException(
            status_code=404,
            detail="Sesión no encontrada",
        ) from exc

    if isinstance(
        exc,
        repository.SchemaNotReadyError,
    ):
        raise HTTPException(
            status_code=503,
            detail=(
                "El esquema SQL "
                "del Asistente IA "
                "no está disponible"
            ),
        ) from exc

    if isinstance(
        exc,
        service.LLMTimeoutError,
    ):
        raise HTTPException(
            status_code=504,
            detail=(
                "El proveedor IA excedió "
                "el tiempo límite"
            ),
        ) from exc

    if isinstance(
        exc,
        service.LLMProviderError,
    ):
        raise HTTPException(
            status_code=503,
            detail=(
                "El proveedor IA "
                "no está disponible"
            ),
        ) from exc

    if isinstance(
        exc,
        ValueError,
    ):
        raise HTTPException(
            status_code=422,
            detail=str(exc),
        ) from exc

    raise exc


@router.get("/health")
async def health(
    current_user: dict = Depends(
        require_explicit_permission(
            IA_PERMISSION
        )
    ),
):
    _current_email(current_user)
    return service.health()


@router.get("/sesiones")
async def listar_sesiones(
    current_user: dict = Depends(
        require_explicit_permission(
            IA_PERMISSION
        )
    ),
):
    try:
        return {
            "success": True,
            "sesiones": (
                service.listar_sesiones(
                    _current_email(
                        current_user
                    )
                )
            ),
        }

    except Exception as exc:
        _translate_error(exc)


@router.post("/sesiones")
async def crear_sesion(
    request: CrearSesionRequest,
    current_user: dict = Depends(
        require_explicit_permission(
            IA_PERMISSION
        )
    ),
):
    try:
        title = (
            request.titulo.strip()
            if request.titulo
            else None
        )

        sesion = service.crear_sesion(
            _current_email(
                current_user
            ),
            title,
        )

        return {
            "success": True,
            "sesion": sesion,
            **sesion,
        }

    except Exception as exc:
        _translate_error(exc)


@router.get(
    "/sesiones/{sesion_id}/mensajes"
)
async def obtener_mensajes(
    sesion_id: UUID,
    current_user: dict = Depends(
        require_explicit_permission(
            IA_PERMISSION
        )
    ),
):
    try:
        return {
            "success": True,
            "mensajes": (
                service.obtener_mensajes(
                    str(sesion_id),
                    _current_email(
                        current_user
                    ),
                )
            ),
        }

    except Exception as exc:
        _translate_error(exc)


@router.delete(
    "/sesiones/{sesion_id}"
)
async def eliminar_sesion(
    sesion_id: UUID,
    current_user: dict = Depends(
        require_explicit_permission(
            IA_PERMISSION
        )
    ),
):
    try:
        service.eliminar_sesion(
            str(sesion_id),
            _current_email(
                current_user
            ),
        )

        return {
            "success": True,
        }

    except Exception as exc:
        _translate_error(exc)


@router.post("/chat")
async def chat(
    request: ChatRequest,
    http_request: Request,
    current_user: dict = Depends(
        require_explicit_permission(
            IA_PERMISSION
        )
    ),
):
    try:
        message = (
            request.mensaje.strip()
        )

        if not message:
            raise ValueError(
                "El mensaje no puede "
                "estar vacío"
            )

        session_id = str(request.sesion_id)
        catalog = query_bridge.build_readonly_catalog(http_request.app)
        prompt_catalog = query_bridge.catalog_for_prompt(catalog, message)
        planned = await service.plan_system_queries(
            session_id,
            message,
            prompt_catalog,
        )
        system_context = await query_bridge.execute_planned_queries(
            http_request.app,
            catalog,
            planned,
